const PRICE_PER_PARTICIPANT_CENTS=18900,GROUP_DISCOUNT_THRESHOLD=4,GROUP_DISCOUNT_FACTOR=.9,AVAILABLE_DATES=["2026-11-07","2026-11-21","2026-12-05","2027-01-16"];function formatEuro(e){return new Intl.NumberFormat("de-DE",{style:"currency",currency:"EUR"}).format(e/100)}function calculateTotalCents(e){let t=e*18900;return e>=4&&(t=Math.round(t*.9)),t}function renderDates(){const e=document.getElementById("course-date");for(const t of AVAILABLE_DATES){const n=document.createElement("option");n.value=t,n.textContent=new Date(t).toLocaleDateString("de-DE"),e.appendChild(n)}}function renderPrice(){const e=document.getElementById("participants"),t=parseInt(e.value,10)||1,n=calculateTotalCents(t),o=document.getElementById("price-summary");o.textContent=t+" \xD7 "+formatEuro(18900)+" = "+formatEuro(n)}async function submitBooking(e){e.preventDefault();const t={date:document.getElementById("course-date").value,participants:parseInt(document.getElementById("participants").value,10)};if(!(await fetch("/api/bookings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)})).ok){alert("Booking failed, please try again.");return}alert("Thank you! We sent you a confirmation email.")}document.addEventListener("DOMContentLoaded",function(){renderDates(),renderPrice(),document.getElementById("participants").addEventListener("input",renderPrice),document.getElementById("booking-form").addEventListener("submit",submitBooking)});
